<?php
$adminPage='cards';$adminTitle='Card operations';$adminPermission='cards.view';require __DIR__.'/../includes/admin_header.php';$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();requirePermission('cards.manage');$id=(int)($_POST['card_id']??0);$status=$_POST['status']??'';if(!in_array($status,['active','disabled'],true))throw new InvalidArgumentException('Invalid card status.');$stmt=$pdo->prepare("UPDATE linked_cards SET status=?,is_default=IF(?='active',is_default,0) WHERE card_id=? AND status<>'removed'");$stmt->execute([$status,$status,$id]);if(!$stmt->rowCount())throw new RuntimeException('Card was not found or already removed.');audit($pdo,'card.status_changed','linked_card',$id,['status'=>$status,'reason'=>substr(trim($_POST['reason']??''),0,500)]);$notice='Card status updated.';}catch(Throwable $e){$error=$e->getMessage();}}$network=$_GET['network']??'';$status=$_GET['status']??'';$params=[];$where=['1=1'];if(in_array($network,['visa','mastercard'],true)){$where[]='c.network=?';$params[]=$network;}if(in_array($status,['active','disabled','removed'],true)){$where[]='c.status=?';$params[]=$status;}$stmt=$pdo->prepare('SELECT c.card_id,c.network,c.last_four,c.provider,c.verification_status,c.status,c.is_default,c.created_at,u.full_name,u.email,(SELECT COUNT(*) FROM card_fundings f WHERE f.card_id=c.card_id) funding_count FROM linked_cards c JOIN users u ON u.user_id=c.user_id WHERE '.implode(' AND ',$where).' ORDER BY c.created_at DESC LIMIT 150');$stmt->execute($params);$cards=$stmt->fetchAll();
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><form class="toolbar" method="get"><div class="field"><label>Network</label><select name="network"><option value="">All networks</option><option value="visa" <?=$network==='visa'?'selected':''?>>Visa</option><option value="mastercard" <?=$network==='mastercard'?'selected':''?>>Mastercard</option></select></div><div class="field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['active','disabled','removed'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach?></select></div><button class="button button-primary">Filter</button></form><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Card</th><th>Provider</th><th>Verification</th><th>Funding events</th><th>Status/action</th></tr></thead><tbody><?php foreach($cards as $card):?><tr><td><?=e($card['full_name'])?><br><small><?=e($card['email'])?></small></td><td><strong><?=e(strtoupper($card['network']))?> •••• <?=e($card['last_four'])?></strong><?=$card['is_default']?' · default':''?></td><td><?=e($card['provider'])?></td><td><?=e($card['verification_status'])?></td><td><?=$card['funding_count']?></td><td><span class="badge <?=e($card['status'])?>"><?=e($card['status'])?></span><?php if(can('cards.manage')&&$card['status']!=='removed'):?><form method="post" class="compact-form" style="margin-top:8px"><?=csrfField()?><input type="hidden" name="card_id" value="<?=$card['card_id']?>"><input type="hidden" name="status" value="<?=$card['status']==='active'?'disabled':'active'?>"><input name="reason" required maxlength="500" placeholder="Reason"><button class="button button-secondary"><?=$card['status']==='active'?'Disable':'Enable'?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php if(!$cards):?><div class="empty">No cards match these filters.</div><?php endif?></section><?php require __DIR__.'/../includes/admin_footer.php';?>
